          lens:'教育社会学', lensId:'education',
          body:'<b>教育社会学</b>关注教育机会如何被制度性地打开或收窄。新生专属服务看似是技术便利，实则降低了异地求学家庭（尤其来自县城、农村）的入学门槛；而电脑随机派位则用程序化公平，回应了“择校焦虑”背后的资源分配问题。',
