      id: 15,
      title: '胖东来公布上半年员工流失数据：仅52人离职、流失率0.5%，平均月薪9598元',
      source: '大象新闻 / 每日经济新闻',
      url: 'https://new.qq.com/rain/a/20260727A096V800',
      kicker: '企业 · 社会学 / 经济学',
      gist: '零售业年均流失率动辄30%，胖东来上半年只走了52个人、流失率0.5%——高工资、长假期、不许加班的"异类"管理，为什么别人学不会。',
      thread: [
        {t:'数据', x:'胖东来披露：上半年员工流失52人、流失率约0.5%，一线员工平均月薪9598元，远高于行业平均水平。'},
        {t:'制度', x:'公司实行每周二闭店、年假最长40天、委屈奖等制度，明确反对加班文化。'},
        {t:'对照', x:'国内零售行业员工年流失率普遍在20%-30%，一线岗位招工难与高流动并存。'},
        {t:'讨论', x:'网友感叹"别人家的公司"；业界持续争论胖东来模式能否走出许昌、被规模化复制。'}
      ],
      interpretations: [
        {
          q:'为什么胖东来的员工不走？高工资就是全部答案吗？',
          naive:'以为多发钱谁都能留住人。',
          lens:'工作社会学', lensId:'work',
          body:'<b>工作社会学</b>指出，劳动体验由报酬、尊严、自主性共同构成。胖东来的委屈奖、强制休假、不许加班，本质是把员工从"人力成本"重新定义为"被尊重的职业人"——当劳动不再以自我损耗为代价，组织认同就替代了跳槽冲动。低流失率是尊严管理的财务报表。',
          aha:'留住人的不是工资条，是上班不用出卖尊严这件事。'
        },
        {
          q:'从经济学看，给零售员工发近万月薪是慈善还是精明？',
          naive:'以为高工资纯属老板大方。',
          lens:'劳动力市场', lensId:'econ_labor',
          body:'<b>劳动力市场</b>中的效率工资理论早有解释：支付高于市场出清水平的工资，能降低离职率、节省招聘培训成本、激励员工自觉维护服务质量——因为失去这份工作的机会成本变高了。0.5%的流失率意味着近乎为零的重置成本，高工资在账面上是支出，在体系里是投资。',
          aha:'高于市场价的工资不是浪费，是买断了员工"随时想走"的选项。'
        }
      ],
